# ============================================================
# DESIGN PATTERNS — Common Solutions to Common Problems
# ============================================================

from abc import ABC, abstractmethod
from typing import Any

# ============================================================
# 1. SINGLETON — Only one instance ever
# ============================================================
class SingletonMeta(type):
    _instances = {}
    def __call__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__call__(*args, **kwargs)
        return cls._instances[cls]

class DatabaseConnection(metaclass=SingletonMeta):
    def __init__(self, url: str = "localhost"):
        self.url = url

db1 = DatabaseConnection("postgresql://...")
db2 = DatabaseConnection()
print(db1 is db2)  # True — same instance!

# ============================================================
# 2. FACTORY — Create objects without specifying exact class
# ============================================================
class Notification(ABC):
    @abstractmethod
    def send(self, message: str): ...

class EmailNotification(Notification):
    def send(self, message): print(f"📧 Email: {message}")

class SMSNotification(Notification):
    def send(self, message): print(f"📱 SMS: {message}")

class PushNotification(Notification):
    def send(self, message): print(f"🔔 Push: {message}")

class NotificationFactory:
    _creators = {
        "email": EmailNotification,
        "sms": SMSNotification,
        "push": PushNotification,
    }

    @classmethod
    def create(cls, notification_type: str) -> Notification:
        creator = cls._creators.get(notification_type)
        if not creator:
            raise ValueError(f"Unknown type: {notification_type}")
        return creator()

    @classmethod
    def register(cls, name: str, creator):
        cls._creators[name] = creator

notif = NotificationFactory.create("email")
notif.send("Hello!")

# ============================================================
# 3. OBSERVER — Publish/Subscribe pattern
# ============================================================
class EventSystem:
    def __init__(self):
        self._listeners: dict[str, list] = {}

    def subscribe(self, event: str, callback):
        self._listeners.setdefault(event, []).append(callback)

    def unsubscribe(self, event: str, callback):
        self._listeners.get(event, []).remove(callback)

    def emit(self, event: str, data: Any = None):
        for callback in self._listeners.get(event, []):
            callback(data)

# Usage
events = EventSystem()
events.subscribe("user_created", lambda u: print(f"Send welcome email to {u}"))
events.subscribe("user_created", lambda u: print(f"Create profile for {u}"))
events.emit("user_created", "Veera")

# ============================================================
# 4. STRATEGY — Swap algorithms at runtime
# ============================================================
from typing import Protocol

class SortStrategy(Protocol):
    def sort(self, data: list) -> list: ...

class BubbleSort:
    def sort(self, data): 
        # Simple sort for small datasets
        return sorted(data)

class QuickSort:
    def sort(self, data):
        # Efficient sort for large datasets
        return sorted(data)

class Sorter:
    def __init__(self, strategy: SortStrategy):
        self._strategy = strategy

    def set_strategy(self, strategy: SortStrategy):
        self._strategy = strategy

    def sort(self, data: list) -> list:
        return self._strategy.sort(data)

# ============================================================
# 5. DECORATOR PATTERN (not Python decorators!)
# ============================================================
class DataSource(ABC):
    @abstractmethod
    def read(self) -> str: ...
    @abstractmethod
    def write(self, data: str): ...

class FileDataSource(DataSource):
    def __init__(self, filename):
        self.filename = filename
    def read(self): return f"Data from {self.filename}"
    def write(self, data): print(f"Writing to {self.filename}")

class DataSourceDecorator(DataSource):
    def __init__(self, wrapped: DataSource):
        self._wrapped = wrapped
    def read(self): return self._wrapped.read()
    def write(self, data): self._wrapped.write(data)

class EncryptionDecorator(DataSourceDecorator):
    def read(self): return f"Decrypted({self._wrapped.read()})"
    def write(self, data): self._wrapped.write(f"Encrypted({data})")

class CompressionDecorator(DataSourceDecorator):
    def read(self): return f"Decompressed({self._wrapped.read()})"
    def write(self, data): self._wrapped.write(f"Compressed({data})")

# Stack decorators!
source = CompressionDecorator(EncryptionDecorator(FileDataSource("data.txt")))
print(source.read())  # Decompressed(Decrypted(Data from data.txt))

# ============================================================
# 6. REPOSITORY PATTERN — Abstract data access
# ============================================================
class UserRepository(Protocol):
    def get(self, user_id: int) -> dict: ...
    def save(self, user: dict) -> None: ...
    def delete(self, user_id: int) -> None: ...
    def find_by_email(self, email: str) -> dict | None: ...

class InMemoryUserRepo:
    def __init__(self):
        self._store: dict[int, dict] = {}

    def get(self, user_id): return self._store.get(user_id)
    def save(self, user): self._store[user["id"]] = user
    def delete(self, user_id): self._store.pop(user_id, None)
    def find_by_email(self, email):
        return next((u for u in self._store.values() if u["email"] == email), None)

# Easy to swap with PostgresUserRepo, MongoUserRepo, etc.

# ============================================================
# 7. BUILDER PATTERN — Step-by-step object construction
# ============================================================
class QueryBuilder:
    def __init__(self):
        self._table = ""
        self._conditions = []
        self._order_by = ""
        self._limit = None

    def from_table(self, table: str) -> "QueryBuilder":
        self._table = table
        return self

    def where(self, condition: str) -> "QueryBuilder":
        self._conditions.append(condition)
        return self

    def order_by(self, field: str) -> "QueryBuilder":
        self._order_by = field
        return self

    def limit(self, n: int) -> "QueryBuilder":
        self._limit = n
        return self

    def build(self) -> str:
        query = f"SELECT * FROM {self._table}"
        if self._conditions:
            query += " WHERE " + " AND ".join(self._conditions)
        if self._order_by:
            query += f" ORDER BY {self._order_by}"
        if self._limit:
            query += f" LIMIT {self._limit}"
        return query

query = (QueryBuilder()
    .from_table("users")
    .where("age > 18")
    .where("status = 'active'")
    .order_by("name")
    .limit(10)
    .build())
print(query)
# SELECT * FROM users WHERE age > 18 AND status = 'active' ORDER BY name LIMIT 10
